import{_ as t,o as r,c as a,ag as s}from"./chunks/framework.DXGyWiRo.js";const u=JSON.parse('{"title":"Architecture Overview","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/index.md","filePath":"architecture/index.md"}'),n={name:"architecture/index.md"};function o(i,e,l,c,d,h){return r(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h1><p>Advisor Agent is an <strong>AI-powered Azure advisory system</strong> built on a multi-tier serverless architecture. It combines Azure Functions with Durable Orchestration, Azure OpenAI, and Azure Resource Graph to deliver actionable recommendations across reliability, cost, retirement, outage remediation, and architecture domains.</p><h2 id="high-level-architecture" tabindex="-1">High-Level Architecture <a class="header-anchor" href="#high-level-architecture" aria-label="Permalink to &quot;High-Level Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────┐       ┌──────────────────────────┐       ┌──────────────────┐</span></span>
<span class="line"><span>│   Client     │──────▶│  Azure Functions Host     │──────▶│  Azure OpenAI    │</span></span>
<span class="line"><span>│  (HTTP/SigR) │◀──────│  (Durable Orchestration)  │◀──────│  (GPT-4o / 4.1) │</span></span>
<span class="line"><span>└──────────────┘       └────────────┬─────────────┘       └──────────────────┘</span></span>
<span class="line"><span>                                    │</span></span>
<span class="line"><span>                       ┌────────────┼────────────┐</span></span>
<span class="line"><span>                       ▼            ▼            ▼</span></span>
<span class="line"><span>                ┌────────────┐ ┌─────────┐ ┌──────────────┐</span></span>
<span class="line"><span>                │ Azure      │ │ Cosmos  │ │ ARM / Azure  │</span></span>
<span class="line"><span>                │ Resource   │ │ DB      │ │ Service      │</span></span>
<span class="line"><span>                │ Graph      │ │         │ │ Health       │</span></span>
<span class="line"><span>                └────────────┘ └─────────┘ └──────────────┘</span></span></code></pre></div><h2 id="core-design-principles" tabindex="-1">Core Design Principles <a class="header-anchor" href="#core-design-principles" aria-label="Permalink to &quot;Core Design Principles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Principle</th><th>How It&#39;s Applied</th></tr></thead><tbody><tr><td><strong>Skill-Based Orchestration</strong></td><td>Capabilities are modular skills defined in a JSON catalog, each with its own tools, system prompt, and model configuration</td></tr><tr><td><strong>LLM-Driven Routing</strong></td><td>Azure OpenAI classifies intent, decomposes tasks, and generates skill-specific prompts — no hard-coded routing rules</td></tr><tr><td><strong>Durable Execution</strong></td><td>Azure Durable Functions provide resilient, resumable, long-running orchestrations with built-in retry and progress tracking</td></tr><tr><td><strong>Context Chaining</strong></td><td>Upstream task outputs are fed into downstream skill prompts, enabling multi-step problem solving with data flow</td></tr><tr><td><strong>Reflection-Based Tool Binding</strong></td><td>Tools are discovered dynamically via <code>ClassName-MethodName</code> patterns — no hardcoded tool references in the orchestrator</td></tr><tr><td><strong>Response Budgeting</strong></td><td>Tool responses are truncated to 15K characters to prevent LLM context window overflow</td></tr></tbody></table><h2 id="three-layer-architecture" tabindex="-1">Three-Layer Architecture <a class="header-anchor" href="#three-layer-architecture" aria-label="Permalink to &quot;Three-Layer Architecture&quot;">​</a></h2><h3 id="_1-functions-layer-advisoragent-functions" tabindex="-1">1. Functions Layer (<code>AdvisorAgent.Functions</code>) <a class="header-anchor" href="#_1-functions-layer-advisoragent-functions" aria-label="Permalink to &quot;1. Functions Layer (\`AdvisorAgent.Functions\`)&quot;">​</a></h3><p>The serverless entry point and durable orchestration host:</p><ul><li><strong>HTTP Triggers</strong> — accept user requests and expose status polling</li><li><strong>Durable Orchestrator</strong> — manages the multi-step pipeline (context → intent → plan → execute)</li><li><strong>Activity Functions</strong> — atomic units of work called by the orchestrator</li><li><strong>DI Container</strong> — wires up credentials, skill catalog, tool instances, and stores</li></ul><h3 id="_2-core-layer-advisoragent-core" tabindex="-1">2. Core Layer (<code>AdvisorAgent.Core</code>) <a class="header-anchor" href="#_2-core-layer-advisoragent-core" aria-label="Permalink to &quot;2. Core Layer (\`AdvisorAgent.Core\`)&quot;">​</a></h3><p>Domain logic, orchestration service, and abstractions:</p><ul><li><strong>AgentOrchestrationService</strong> — the brain: LLM calls for context extraction, intent classification, task decomposition, and skill execution</li><li><strong>Skill Definitions</strong> — metadata-driven skill catalog loaded from JSON</li><li><strong>Task Planning</strong> — DAG-based task plans with topological sort and cycle detection</li><li><strong>Conversation Store</strong> — multi-turn history persistence (Cosmos DB or in-memory)</li><li><strong>Domain Models</strong> — <code>AzureContext</code>, <code>UserIntent</code>, <code>ConversationTurn</code>, <code>AdvisorAgentResponse</code></li></ul><h3 id="_3-tools-layer-advisoragent-tools" tabindex="-1">3. Tools Layer (<code>AdvisorAgent.Tools</code>) <a class="header-anchor" href="#_3-tools-layer-advisoragent-tools" aria-label="Permalink to &quot;3. Tools Layer (\`AdvisorAgent.Tools\`)&quot;">​</a></h3><p>Concrete Azure data retrieval capabilities:</p><ul><li><strong>ToolBase</strong> — shared ARM REST and Resource Graph helpers</li><li><strong>7 Tool Classes</strong> — each exposes methods that the LLM can invoke during skill execution</li><li>All tools use the caller&#39;s Bearer token for Azure API access</li></ul><h2 id="key-technologies" tabindex="-1">Key Technologies <a class="header-anchor" href="#key-technologies" aria-label="Permalink to &quot;Key Technologies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Technology</th><th>Purpose</th></tr></thead><tbody><tr><td>Azure Functions (isolated)</td><td>Serverless compute host</td></tr><tr><td>Azure Durable Functions</td><td>Orchestration, sub-orchestration, activity coordination</td></tr><tr><td>Azure OpenAI (GPT-4o)</td><td>Intent classification, task decomposition, skill execution</td></tr><tr><td>Azure Resource Graph</td><td>KQL-based resource and advisor recommendation queries</td></tr><tr><td>Azure Cosmos DB</td><td>Conversation history persistence</td></tr><tr><td>Azure SignalR</td><td>Real-time progress updates to clients</td></tr><tr><td>Microsoft.Extensions.AI</td><td>AI function invocation middleware</td></tr><tr><td>DefaultAzureCredential</td><td>Managed identity for Azure SDK calls</td></tr></tbody></table>`,18)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
